// ================================================================
// Nœud Code : Email Trigger (IMAP) — version optimisée
// - Lit les courriels non lus (max 50) de INBOX
// - Décode correctement quoted-printable / base64 + charset
// - Identifie text/plain et text/html via bodyStructure (pas par position)
// - Sortie compatible avec le reste du workflow (metadata.uid, etc.)
// ================================================================
const { ImapFlow } = require('imapflow');

const MAX_EMAILS = 50;

// Logger vide pour éviter le conflit pino/sandbox n8n
const silentLogger = {
  debug: () => {}, info: () => {}, warn: () => {}, error: () => {}, trace: () => {},
  child: () => silentLogger
};

// ---------- Utilitaires MIME ----------
function indexParts(node, map = {}) {
  if (!node) return map;
  if (node.part) {
    map[node.part] = {
      type:     (node.type || '').toLowerCase(),               // ex: text/plain
      encoding: (node.encoding || '').toLowerCase(),           // ex: quoted-printable
      charset:  (node.parameters?.charset || 'utf-8').toLowerCase()
    };
  }
  (node.childNodes || []).forEach(c => indexParts(c, map));
  return map;
}

function decodeQP(str) {
  const s = str.replace(/=\r?\n/g, ''); // coupures de ligne "soft"
  const out = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '=' && /^[0-9A-Fa-f]{2}$/.test(s.substr(i + 1, 2))) {
      out.push(parseInt(s.substr(i + 1, 2), 16));
      i += 2;
    } else {
      out.push(s.charCodeAt(i) & 0xff);
    }
  }
  return Buffer.from(out);
}

function decodeBody(buf, info) {
  let enc = info?.encoding || '';
  const charset = info?.charset || 'utf-8';
  const raw = buf.toString('latin1');

  // Filet de sécurité : encodage inconnu mais contenu qui ressemble à du QP
  if (!enc && (raw.match(/=[0-9A-F]{2}/g) || []).length >= 2) enc = 'quoted-printable';
  if (!enc) {
    const compact = raw.replace(/\s/g, '');
    if (compact.length >= 16 && compact.length % 4 === 0 && /^[A-Za-z0-9+\/]+={0,2}$/.test(compact)) {
      const t = Buffer.from(compact, 'base64').toString('utf-8');
      const printable = (t.match(/[\x09\x0A\x0D\x20-\x7E\u00A0-\uFFFF]/g) || []).length;
      if (!t.includes('\ufffd') && printable / t.length > 0.95) enc = 'base64';
    }
  }

  let bytes;
  if (enc === 'base64')                bytes = Buffer.from(raw.replace(/\s/g, ''), 'base64');
  else if (enc === 'quoted-printable') bytes = decodeQP(raw);
  else                                 bytes = buf;

  try { return new TextDecoder(charset).decode(bytes); }
  catch (_) { return bytes.toString('utf-8'); }
}

function formatAddress(addr) {
  if (!addr) return '';
  return addr.name ? `${addr.name} <${addr.address}>` : (addr.address || '');
}

// ---------- Traitement ----------
const client = new ImapFlow({
  host:   $env.IONOS_IMAP_HOST,
  port:   993,
  secure: true,
  auth:   { user: $env.IONOS_USER, pass: $env.IONOS_PASS },
  logger: silentLogger
});

const emails = [];

try {
  await client.connect();
  const lock = await client.getMailboxLock('INBOX');

  try {
    const uids = await client.search({ seen: false }, { uid: true });

    if (!uids || uids.length === 0) {
      return []; // aucun courriel : on arrête ici, rien ne descend dans le workflow
    }

    const toFetch = uids.slice(-MAX_EMAILS);

    for await (const msg of client.fetch(
      toFetch,
      {
        uid:           true,
        envelope:      true,
        bodyParts:     ['1', '2', 'TEXT'],
        bodyStructure: true,
        flags:         true
      },
      { uid: true }
    )) {
      const env = msg.envelope || {};

      // Infos de chaque partie (type, encodage, charset)
      const parts = indexParts(msg.bodyStructure);
      parts['TEXT'] = parts['TEXT'] || {
        type:     (msg.bodyStructure?.type || '').toLowerCase(),
        encoding: (msg.bodyStructure?.encoding || '').toLowerCase(),
        charset:  (msg.bodyStructure?.parameters?.charset || 'utf-8').toLowerCase()
      };

      // Message simple (non multipart) : la partie "1" = le message racine
      if (!(msg.bodyStructure?.childNodes || []).length) parts['1'] = parts['1'] || parts['TEXT'];

      let textPlain = '';
      let textHtml  = '';

      if (msg.bodyParts) {
        for (const [key, buf] of msg.bodyParts) {
          const info = parts[key];
          const text = decodeBody(buf, info);
          const type = info?.type || '';

          if (type === 'text/html')       { if (!textHtml)  textHtml  = text; }
          else if (type === 'text/plain') { if (!textPlain) textPlain = text; }
          else if (key === '2')           { if (!textHtml)  textHtml  = text; }
          else if (key === '1')           { if (!textPlain) textPlain = text; }
          else if (key === 'TEXT')        { if (!textPlain) textPlain = text; }
        }
      }

      emails.push({
        json: {
          from:      formatAddress(env.from?.[0] || env.sender?.[0] || env.replyTo?.[0]),
          to:        formatAddress(env.to?.[0]),
          subject:   env.subject   || '',
          date:      env.date?.toISOString() || new Date().toISOString(),
          messageId: env.messageId || '',
          textPlain,
          textHtml,
          metadata: {
            'message-id': env.messageId || '',
            uid: msg.uid
          }
        }
      });
    }
  } finally {
    lock.release();
  }
} catch (error) {
  throw new Error('Erreur IMAP: ' + error.message);
} finally {
  try { await client.logout(); } catch (_) {}
}

return emails;
